/* Cena "neon bruma": quadro de missoes do dojo. O aluno cria a <ul id="lista">; o js fixo a preenche. */
[data-reduz="1"] *{animation:none!important;transition:none!important}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;padding:34px 18px;font-family:system-ui,sans-serif;color:#efe9ff;
  display:flex;flex-direction:column;align-items:center;
  background:
    radial-gradient(56% 30% at 80% 0%,rgba(255,190,120,.14),transparent 70%),
    linear-gradient(180deg,#110e28 0%,#231a4a 58%,#472a4e 100%)}
body::before{content:"";position:fixed;left:0;right:0;bottom:0;height:20vh;pointer-events:none;
  background:radial-gradient(70% 100% at 50% 100%,rgba(224,205,255,.12),transparent 72%);
  animation:respirar 9s ease-in-out infinite alternate}
@keyframes respirar{from{opacity:.55}to{opacity:1}}
h2{margin:0;font-size:21px;letter-spacing:.22em;text-transform:uppercase;color:#c9f5df;text-align:center}
h2::after{content:"";display:block;width:72%;height:2px;margin:10px auto 0;border-radius:2px;
  background:linear-gradient(90deg,transparent,#64e6b4,transparent);
  box-shadow:0 0 14px rgba(100,230,180,.8)}
#lista{list-style:none;margin:20px 0 0;padding:14px 16px;width:min(92vw,340px);position:relative;border-radius:14px;
  background:linear-gradient(165deg,rgba(38,28,74,.93),rgba(21,14,43,.93));
  border:1px solid rgba(100,230,180,.3)}
#lista::before{content:"";position:absolute;inset:-48px;z-index:-1;border-radius:50%;
  background:radial-gradient(closest-side,rgba(100,230,180,.14),transparent 72%)}
li{position:relative;padding:11px 8px 11px 32px;font-size:16px;color:#e9e2ff;
  border-bottom:1px solid rgba(159,240,205,.14)}
li:last-child{border-bottom:0}
li::before{content:"";position:absolute;left:9px;top:50%;width:9px;height:9px;border-radius:2px;
  transform:translateY(-50%) rotate(45deg);background:#7dedbb;
  box-shadow:0 0 10px rgba(125,237,187,.9),0 0 24px rgba(125,237,187,.4)}
li:nth-child(2)::before{background:#ffcf7d;box-shadow:0 0 10px rgba(255,207,125,.9),0 0 24px rgba(255,207,125,.4)}
li:nth-child(3)::before{background:#c78bff;box-shadow:0 0 10px rgba(199,139,255,.9),0 0 24px rgba(199,139,255,.4)}
/* Enquanto a <ul id="lista"> nao existe, o quadro exibe um aviso apagado */
body::after{content:"o quadro aguarda a lista de tarefas...";margin-top:22px;padding:16px 20px;
  border:1px dashed rgba(196,179,230,.4);border-radius:12px;font-size:13px;color:#b9addc}
body:has(#lista)::after{content:none}

exercicios.web_js:
window.tarefas = ["Estudar Python", "Revisar PRs", "Fazer deploy"];
window.addEventListener("DOMContentLoaded", function () {
  var ul = document.getElementById("lista");
  if (!ul) return;
  window.tarefas.forEach(function (t) {
    var li = document.createElement("li");
    li.textContent = t;
    ul.appendChild(li);
  });
});

exercicios.explicacao_md:
Um back-end (a lógica) só é útil quando o front (a tela) o **chama**. Ligar os dois é ler os campos, chamar a função e mostrar o resultado:

```js
botao.addEventListener("click", function () {
  var a = Number(campoA.value);
  resultado.textContent = minhaFuncao(a);
});
```

