window.produtos = [
  { nome: "Notebook" },
  { nome: "Mouse" },
  { nome: "Monitor" },
  { nome: "Cadeira" }
];

function filtrarPorNome(lista, termo) {
  var t = termo.trim().toLowerCase();
  return lista.filter(function (p) {
    return p.nome.toLowerCase().indexOf(t) !== -1;
  });
}

function renderizar(lista) {
  var alvo = document.getElementById("lista");
  alvo.innerHTML = lista.map(function (p) {
    return "<div class='item'>" + p.nome + "</div>";
  }).join("");
  document.getElementById("vazio").hidden = lista.length !== 0;
}

renderizar(window.produtos);

