.janela::before{content:"";position:absolute;inset:0;opacity:0;transition:opacity .5s;
  background:radial-gradient(1.6px 1.6px at 18% 26%,#fff 60%,transparent 61%),
    radial-gradient(1.2px 1.2px at 64% 18%,#fff 60%,transparent 61%),
