    radial-gradient(1px 1px at 86% 38%,#fff 60%,transparent 61%)}
.astro{position:absolute;top:20px;left:24px;width:34px;height:34px;border-radius:50%;
  background:radial-gradient(circle at 40% 36%,#fff7e2 0 40%,#ffd98a 64%,rgba(255,190,110,0) 74%);
