.quarto{position:relative;height:36px;margin-top:10px}
.abajur{position:absolute;left:10px;bottom:14px;width:26px;height:14px;
  background:linear-gradient(180deg,#e7a75f,#cf8a48);
  clip-path:polygon(18% 0,82% 0,100% 100%,0 100%);transition:filter .5s}
