/* Cena: totem de vitrine no Distrito Dourado (anoitecer ambar) */
body{margin:0;min-height:100vh;font-family:"Segoe UI",system-ui,sans-serif;color:#f6eddc;background:linear-gradient(180deg,#191330 0%,#2c1e42 50%,#5c3a3c 85%,#96603e 100%)}
.totem{max-width:430px;margin:26px auto 0;padding:14px 14px 16px;border-radius:18px;border:1px solid rgba(255,196,120,.35);background:linear-gradient(180deg,#241a3d,#181330);box-shadow:0 0 40px rgba(255,170,80,.16),0 18px 40px rgba(0,0,0,.4)}
.topo{display:flex;align-items:center;gap:8px;padding:2px 4px 12px;font-size:12px;font-weight:600;letter-spacing:.22em;text-transform:uppercase;color:#ffd9a0;text-shadow:0 0 10px rgba(255,196,120,.55)}
.lampada{width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#fff4e0,#ffb35c 60%,rgba(255,179,92,0) 78%);box-shadow:0 0 12px rgba(255,179,92,.9);animation:piscar 3.4s infinite}
@keyframes piscar{0%,90%,100%{opacity:1}95%{opacity:.4}}
.abas{display:flex;gap:6px;margin-bottom:10px}
.aba{flex:1;font-size:15px;padding:9px 8px;border:1px solid rgba(255,214,170,.18);border-radius:10px 10px 4px 4px;cursor:pointer;color:#dccfb8;background:linear-gradient(180deg,rgba(255,244,224,.08),rgba(255,244,224,.02))}
.aba:hover{color:#fff4e0;border-color:rgba(255,214,170,.4)}
.aba:focus-visible{outline:2px solid #ffd9a0;outline-offset:2px}
.aba.ativa{color:#2b1a10;font-weight:600;border-color:rgba(255,244,224,.7);background:linear-gradient(180deg,#ffe9c4,#f0b35e);box-shadow:0 0 18px rgba(255,179,92,.5),0 0 40px rgba(255,179,92,.18)}
/* o teste compara o display com "block": manter exatamente none/block */
.painel{display:none;min-height:76px;padding:14px;font-size:15px;line-height:1.55;border:1px solid rgba(255,214,170,.22);border-radius:10px;color:#f6eddc;background:radial-gradient(120% 90% at 50% 0%,rgba(255,196,120,.10),rgba(255,196,120,0) 60%)}
.painel.ativo{display:block;animation:acender .25s ease-out}
@keyframes acender{from{opacity:0;transform:translateY(4px)}}
/* sombra tintada do totem, nunca preto chapado */
.pe{width:190px;height:16px;margin:2px auto 26px;border-radius:50%;background:radial-gradient(closest-side,rgba(255,150,70,.30),rgba(255,150,70,0))}

exercicios.web_js:
var abas = document.querySelectorAll(".aba");
var paineis = document.querySelectorAll(".painel");

function mostrarAba(alvo) {
  paineis.forEach(function (p) {
    p.classList.toggle("ativo", p.id === alvo);
  });
  abas.forEach(function (a) {
    a.classList.toggle("ativa", a.dataset.alvo === alvo);
  });
}

// Ligue cada botão .aba: no clique, chame mostrarAba(a.dataset.alvo).

exercicios.solucao_js:
var abas = document.querySelectorAll(".aba");
var paineis = document.querySelectorAll(".painel");

function mostrarAba(alvo) {
  paineis.forEach(function (p) {
    p.classList.toggle("ativo", p.id === alvo);
  });
  abas.forEach(function (a) {
    a.classList.toggle("ativa", a.dataset.alvo === alvo);
  });
}

abas.forEach(function (a) {
  a.addEventListener("click", function () {
    mostrarAba(a.dataset.alvo);
  });
});

