/* Cena: balcão do Empório Coral (distrito coral, anoitecer) */
body{margin:0;min-height:100vh;font-family:"Segoe UI",system-ui,sans-serif;color:#ffe9dc;background:linear-gradient(180deg,#221331 0%,#45213e 45%,#83394a 80%,#c25f4a 100%)}
.loja{max-width:400px;margin:22px auto;padding:0 14px;text-align:center}
.letreiro{margin:0 0 14px;font-size:20px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#ffe3d4;text-shadow:0 0 16px rgba(255,120,90,.8),0 0 40px rgba(255,120,90,.35)}
.balcao{padding:16px;border-radius:16px;border:1px solid rgba(255,150,110,.35);background:linear-gradient(180deg,rgba(255,244,224,.06),rgba(10,4,14,.30));box-shadow:0 0 34px rgba(255,110,80,.16)}
.produto{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:12px;text-align:left;border:1px solid rgba(255,214,170,.18);background:rgba(255,244,224,.05)}
/* a lanterna: nucleo quase branco quente com halo coral difuso */
.lanterna{flex:none;width:34px;height:44px;border-radius:8px 8px 11px 11px;border:1px solid rgba(255,228,190,.6);background:radial-gradient(circle at 50% 42%,#fff4e0 0 5px,rgba(255,179,92,.85) 45%,rgba(96,38,40,.95) 78%);box-shadow:0 0 22px rgba(255,170,110,.6);animation:brilhar 4s ease-in-out infinite}
@keyframes brilhar{50%{box-shadow:0 0 30px rgba(255,190,130,.85)}}
.info strong{display:block;font-size:16px;color:#fff1e6}
.preco{font-size:13px;color:#ffc0a6}
.contador{display:flex;align-items:center;justify-content:center;gap:14px;margin:16px 0 4px}
/* teclas mecanicas: sombra de curso embaixo, afundam no clique */
.btn{width:46px;height:46px;font-size:20px;border:1px solid rgba(255,214,170,.5);border-radius:12px;cursor:pointer;color:#3a1626;background:linear-gradient(180deg,#ffd9c4,#ff9a70);box-shadow:0 0 16px rgba(255,140,100,.45),0 4px 0 rgba(80,22,32,.7)}
.btn:hover{background:linear-gradient(180deg,#ffe4d4,#ffab84)}
.btn:active{transform:translateY(3px);box-shadow:0 0 16px rgba(255,140,100,.45),0 1px 0 rgba(80,22,32,.7)}
