/* visor do balcão */
#qtd{display:inline-block;min-width:58px;padding:9px 6px;font-size:24px;border-radius:10px;color:#fff4e0;border:1px solid rgba(255,150,110,.4);background:rgba(18,6,16,.55);text-shadow:0 0 10px rgba(255,170,120,.7)}
/* cupom fiscal */
.cupom{max-width:230px;margin:16px auto 0;padding:10px 12px;font-size:17px;color:#4a2018;border-radius:4px 4px 12px 12px;background:linear-gradient(180deg,#fff7ea,#ffe9d2);box-shadow:0 6px 18px rgba(60,15,25,.35)}
.cupom #total{color:#8a2432}
/* sombra eliptica tintada sob o balcão */
.sombra{width:230px;height:18px;margin:10px auto 0;border-radius:50%;background:radial-gradient(closest-side,rgba(255,120,80,.30),rgba(255,120,80,0))}

