var preco = 30;
var qtd = 0;

function atualizar() {
  document.getElementById("qtd").textContent = qtd;
  document.getElementById("total").textContent = "R$ " + qtd * preco;
}

document.getElementById("mais").addEventListener("click", function () {
  qtd = qtd + 1;
  atualizar();
});
document.getElementById("menos").addEventListener("click", function () {
  qtd = qtd + 1;   // BUG: deveria diminuir e nunca descer abaixo de 0
  atualizar();
});

atualizar();

exercicios.solucao_js:
var preco = 30;
var qtd = 0;

function atualizar() {
  document.getElementById("qtd").textContent = qtd;
  document.getElementById("total").textContent = "R$ " + qtd * preco;
}

document.getElementById("mais").addEventListener("click", function () {
  qtd = qtd + 1;
  atualizar();
});
document.getElementById("menos").addEventListener("click", function () {
  if (qtd > 0) qtd = qtd - 1;
  atualizar();
});

atualizar();

exercicios.web_css:
/* Cena: barra do Observatório Aurora (distrito verde, noite) */
body{margin:0;min-height:100vh;font-family:"Segoe UI",system-ui,sans-serif;color:#d9ffe9;background:linear-gradient(180deg,#0d1424 0%,#12263a 45%,#1c4a42 80%,#2f6e52 100%)}
/* aurora difusa no topo do céu, sem blur por elemento */
.aurora{position:fixed;inset:0 0 auto 0;height:230px;pointer-events:none;background:radial-gradient(70% 130% at 28% -30%,rgba(92,230,160,.22),rgba(92,230,160,0) 65%),radial-gradient(60% 120% at 78% -35%,rgba(120,180,255,.15),rgba(120,180,255,0) 60%)}
.estacao{max-width:440px;margin:26px auto;padding:0 14px}
.barra{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;border-radius:14px;border:1px solid rgba(120,230,180,.35);background:linear-gradient(180deg,rgba(240,255,246,.07),rgba(8,18,16,.45));box-shadow:0 0 30px rgba(90,220,160,.16)}
.marca{display:flex;align-items:center;gap:9px;font-size:13px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#eafff3;text-shadow:0 0 12px rgba(120,230,180,.6)}
.pulso{width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#f2fff6,#5ce6a0 60%,rgba(92,230,160,0) 80%);box-shadow:0 0 14px rgba(92,230,160,.9);animation:pulsar 2.8s ease-in-out infinite}
@keyframes pulsar{50%{transform:scale(1.35)}}
.suspenso{position:relative}
#menuBtn{font-size:15px;font-weight:600;padding:9px 16px;border:1px solid rgba(180,255,215,.5);border-radius:10px;cursor:pointer;color:#0d2a1e;background:linear-gradient(180deg,#d9ffe9,#7ee6ae);box-shadow:0 0 18px rgba(92,230,160,.45)}
#menuBtn:hover{box-shadow:0 0 26px rgba(120,255,190,.65)}
#menuBtn:active{transform:translateY(1px)}
#menuBtn:focus-visible{outline:2px solid #eaffe0;outline-offset:3px}
#menu{position:absolute;right:0;top:calc(100% + 10px);z-index:5;width:190px;margin:0;padding:8px;list-style:none;border-radius:12px;border:1px solid rgba(120,230,180,.4);background:linear-gradient(180deg,rgba(15,30,25,.97),rgba(9,19,16,.97));box-shadow:0 0 34px rgba(92,230,160,.25),0 16px 30px rgba(0,0,0,.5)}
/* seta que liga o painel à barra */
#menu::before{content:"";position:absolute;top:-5px;right:24px;width:8px;height:8px;transform:rotate(45deg);background:#0f1e19;border-left:1px solid rgba(120,230,180,.4);border-top:1px solid rgba(120,230,180,.4)}
#menu li{padding:9px 10px;border-radius:8px;font-size:14px;color:#d9ffe9}
#menu li+li{margin-top:2px}
#menu li:hover{background:rgba(92,230,160,.14);color:#f6fff9}
#menu:not(.oculto){animation:descer .22s ease-out}
@keyframes descer{from{opacity:0;transform:translateY(-8px)}}
.oculto{display:none!important}
.legenda{margin:16px 2px 0;font-size:13px;color:#a6d8bb;text-align:center}

exercicios.web_js:
var btn = document.getElementById("menuBtn");
var menu = document.getElementById("menu");

function abrir() {
  menu.classList.remove("oculto");
  btn.setAttribute("aria-expanded", "true");
}
function fechar() {
  menu.classList.add("oculto");
  btn.setAttribute("aria-expanded", "false");
}

// Ligue o clique do #menuBtn: alterne entre abrir() e fechar()
// conforme o #menu esteja escondido (classe "oculto") ou visível.

exercicios.solucao_js:
var btn = document.getElementById("menuBtn");
var menu = document.getElementById("menu");

function abrir() {
  menu.classList.remove("oculto");
  btn.setAttribute("aria-expanded", "true");
}
function fechar() {
  menu.classList.add("oculto");
  btn.setAttribute("aria-expanded", "false");
}

btn.addEventListener("click", function () {
  if (menu.classList.contains("oculto")) {
    abrir();
  } else {
    fechar();
  }
});
